    "'$start = [Math]::Max(0, $i-1)
    $end = [Math]::Min($lines.Count-1, $i+12)
    Write-Output ("----- L{0}-{1} -----" -f ($start+1), ($end+1))
    for ($j=$start; $j -le $end; $j++) {
      Write-Output ("{0}|{1}" -f ($j+1), $lines[$j])
    }
  }
}'

